const SILENT_TYPES = ['sleep', 'rest', 'break'];
const mins = (n) => n === 1 ? 'دقيقة' : n === 2 ? 'دقيقتين' : (n >= 3 && n <= 10) ? n + ' دقايق' : n + ' دقيقة';
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (SILENT_TYPES.includes(String(r.session_type || '').toLowerCase())) continue;
  const fixed = r.is_fixed === true || r.is_fixed === 't';
  const span = `🕒 من ${r.start_t} إلى ${r.end_t}`;
  const lines = [];
  if (r.kind === 'pre') {
    lines.push(r.mins_to_start <= 0 ? `⏳ دلوقتي: ${r.title}` : `⏳ بعد ${mins(r.mins_to_start)}: ${r.title}`, span);
    if (r.objective) lines.push(`🎯 ${r.objective}`);
    if (r.tasks) lines.push(`📌 ${r.tasks}`);
  } else if (r.kind === 'start') {
    if (fixed) {
      lines.push(`🏫 دلوقتي: ${r.title}`, span);
    } else {
      lines.push(`📚 بدأت جلسة: ${r.title}`, `${span}${r.planned_minutes ? ' (' + mins(r.planned_minutes) + ')' : ''}`);
      if (r.objective) lines.push(`🎯 ${r.objective}`);
      if (r.tasks) lines.push(`📌 ${r.tasks}`);
      lines.push('ركّز، وأنا هبلغك لما تخلص.');
    }
  } else if (r.kind === 'end') {
    lines.push(`✅ خلصت: ${r.title}`);
    if (r.next_title) {
      lines.push(`➡️ الجاية: ${r.next_title}`, `🕒 من ${r.next_start} إلى ${r.next_end}`);
      if (r.next_objective) lines.push(`🎯 ${r.next_objective}`);
    } else {
      lines.push('مفيش جلسات تانية النهارده 🎉');
    }
    if (!fixed) lines.push(`لو ماذاكرتش أو خلصت بدري قولي، مثلًا: «ما ذاكرتش ${r.title}»`);
  }
  if (lines.length) out.push({ json: { chat: r.telegram_id, text: lines.join('\n') } });
}
return out;
